MENU_H       = 0 if IS_MAC else 26
TOOLBAR_H    = 36
# G2 Phase 4 — Maya-style Shelf row beneath the toolbar.
# Tab strip (`SHELF_TAB_H`) lists the available shelves; the active
# shelf's icon strip (`SHELF_STRIP_H`) renders just below.
SHELF_TAB_H   = 22
SHELF_STRIP_H = 38
SHELF_H       = SHELF_TAB_H + SHELF_STRIP_H
TOOLBOX_W    = 116
RIGHT_W      = 320
PROJECT_H    = 200
# G4 Phase 7a — Maya Channel Box section that sits between the Project
# Explorer (top) and the Properties pane (bottom). Shows the keyable
# attributes of the active selection in a compact list so the user
# can scan / scrub animation values without expanding the full
# Attribute Editor.
CHANNEL_BOX_H = 184
FORM_INSET   = 24
TITLE_BAR_H  = 26
STATUS_H     = 22
TIMELINE_H   = 164                  # bottom dock for keyframe scrub UI
# G3 Phase 5 — Maya-style transport-button row at the top of the
# timeline. Drawn inside TIMELINE_H, so this constant doesn't break
# any layouts that anchor relative to HEIGHT - STATUS_H - TIMELINE_H.
TIMELINE_TRANSPORT_H = 32
# Self-host migration: the Designer's host window is fully borderless
# (transparent=True, title_bar=False), so we paint our own custom
# title strip at the top  Elysium-styled traffic lights, drag
# region, title text. Height matches an OS title bar plus a touch
# of breathing room for the chromatic gloss to read.
#
# The title strip's height is folded into MENU_H so every chrome
# surface that anchors at `MENU_H` (toolbar, in-window menu bar,
# shelf, form area via TOP_OFFSET) automatically shifts down to
# leave the strip uncovered.
TITLE_STRIP_H = 32


def _aether_debug_log(msg: str) -> None:
    """Append a timestamped line to /tmp/elysium-aether-debug.log so we
    can diagnose Aether wiring from the bundled .app where stdout is
    suppressed. Cheap to call — no-op if the path isn't writable."""
    try:
        import time as _t
        with open("/tmp/elysium-aether-debug.log", "a") as f:
            f.write(f"[{_t.strftime('%H:%M:%S')}] {msg}\n")
    except Exception:
        pass
MENU_H       += TITLE_STRIP_H
TOP_OFFSET   = MENU_H + TOOLBAR_H + SHELF_H


def _apply_chrome_layout_manifest() -> None:
    """Self-host migration, Stage 3g (spec §9): pull window-geometry
    constants from ``designer-chrome.esk/manifest.json`` so authors
    who fork the chrome bundle can tune column widths / strip heights
    without editing Python. Failures (missing file, bad JSON, missing
    keys) silently fall back to the module-level defaults above so
    the Designer never refuses to launch over a chrome typo."""
    global MENU_H, TOOLBAR_H, SHELF_TAB_H, SHELF_STRIP_H, SHELF_H
    global TOOLBOX_W, RIGHT_W, PROJECT_H, CHANNEL_BOX_H, TITLE_BAR_H
    global STATUS_H, TIMELINE_H, TIMELINE_TRANSPORT_H, TOP_OFFSET
    try:
        from pathlib import Path as _P
        manifest_path = (_P(__file__).parent
                          / "designer-chrome.esk" / "manifest.json")
        if not manifest_path.is_file():
            return
        import json as _json
        layout = _json.loads(
            manifest_path.read_text()).get("layout") or {}
    except Exception:
        return
    if "menu_h_mac" in layout and IS_MAC:
        MENU_H = int(layout["menu_h_mac"])
    elif "menu_h_other" in layout and not IS_MAC:
        MENU_H = int(layout["menu_h_other"])
    if "toolbar_h"            in layout: TOOLBAR_H            = int(layout["toolbar_h"])
    if "shelf_tab_h"          in layout: SHELF_TAB_H          = int(layout["shelf_tab_h"])
    if "shelf_strip_h"        in layout: SHELF_STRIP_H        = int(layout["shelf_strip_h"])
    if "toolbox_w"            in layout: TOOLBOX_W            = int(layout["toolbox_w"])
    if "right_w"              in layout: RIGHT_W              = int(layout["right_w"])
    if "project_h"            in layout: PROJECT_H            = int(layout["project_h"])
    if "channel_box_h"        in layout: CHANNEL_BOX_H        = int(layout["channel_box_h"])
    if "title_bar_h"          in layout: TITLE_BAR_H          = int(layout["title_bar_h"])
    if "status_h"             in layout: STATUS_H             = int(layout["status_h"])
    if "timeline_h"           in layout: TIMELINE_H           = int(layout["timeline_h"])
    if "timeline_transport_h" in layout: TIMELINE_TRANSPORT_H = int(layout["timeline_transport_h"])
    # The custom Elysium title strip lives ABOVE the menu bar at the
    # very top of the chrome. Fold its height into MENU_H so every
    # surface that anchors at `MENU_H` (toolbar, in-window menu bar,
    # shelf, form area via TOP_OFFSET) automatically shifts down to
    # leave the title strip uncovered.
    MENU_H    += TITLE_STRIP_H
    # Recompute derived constants now that the inputs may have changed.
    SHELF_H    = SHELF_TAB_H + SHELF_STRIP_H
    TOP_OFFSET = MENU_H + TOOLBAR_H + SHELF_H


_apply_chrome_layout_manifest()


# Brush palette diagnostic instrumentation. Enabled by launching with
# ``DESIGNER_BRUSH_PALETTE_DEBUG=1``. Prints to stderr; no-op when
# unset so production sessions pay zero cost.
_BRUSH_DEBUG_ENV = "DESIGNER_BRUSH_PALETTE_DEBUG"
_BRUSH_DEBUG = bool(os.environ.get(_BRUSH_DEBUG_ENV, ""))

# Designer-wide debug logger. Enabled by `ELYSIUM_DESIGNER_DEBUG=1`.
# Each call prints to stderr with a tag prefix and is no-op when the
# env var is unset (so production sessions pay zero cost). Designed
# to surface per-frame paint cost + dispatch routing when the user
# reports unresponsiveness or a click that "does nothing".
_ELY_DEBUG = bool(os.environ.get("ELYSIUM_DESIGNER_DEBUG", ""))


def _edbg(tag: str, msg: str) -> None:
    if _ELY_DEBUG:
        print(f"[ely:{tag}] {msg}", file=sys.stderr, flush=True)


def _bdbg(msg: str) -> None:
    """Log a brush-palette diagnostic line to stderr when the env var
    DESIGNER_BRUSH_PALETTE_DEBUG is set. Otherwise a no-op."""
    if _BRUSH_DEBUG:
        print(f"[bp] {msg}", file=sys.stderr, flush=True)


