# --- Models ---------------------------------------------------------------

@dataclass
class AnimState:
    """A snapshot of transform offsets a Placement can interpolate to."""
    name:     str = "default"
    dx:       float = 0.0
    dy:       float = 0.0
    scale:    float = 1.0
    opacity:  float = 1.0
    rotation: float = 0.0    # radians
    duration: float = 0.4    # seconds to reach this state
    # Per-state easing — drives the curve of the transition INTO this
    # state. One of: linear, ease_in, ease_out, ease_in_out, spring,
    # ease-in-sine, ease-out-cubic, ... (see elysium.anim.EASINGS).
    easing:   str   = "ease_out"
    # Optional wing-pose override (Mesh3D only). When non-None, the
    # placement's `mesh_flap_freq` is forced to 0 and `mesh_flap` is
    # eased toward `mesh_flap_target` while this state is active. Use
    # to "freeze" the wings in a specific pose at the end of a landing
    # animation (e.g. wings folded up with tips touching).
    mesh_flap_target: float | None = None

    def to_json(self) -> dict: return self.__dict__.copy()
    @classmethod
    def from_json(cls, d: dict) -> "AnimState":
        return cls(**{k: d[k] for k in d if k in cls.__dataclass_fields__})


@dataclass
class Placement:
    """A control / Shape / Image placed on the canvas."""
    kind: str
    x: float
    y: float
    w: float
    h: float
    name: str = ""
    props: dict = field(default_factory=dict)
    # Shape-specific:
    shape: str = ""
    points: list[tuple[float, float]] = field(default_factory=list)
    path_d: str = ""
    fill:   Color = (122, 88, 244, 255)
    stroke: Color = (0, 0, 0, 0)
    stroke_w: float = 1.5
    gradient_end:   Color | None = None
    gradient_angle: float = 90.0       # degrees, 0=horizontal, 90=vertical
    # Image-specific:
    image_path: str = ""
    # Hotspot: invisible-in-Preview Shape used purely as a click target.
    is_hotspot: bool = False
    # Marker for lasso/selection-style placements that should render with
    # marching-ants stroke instead of a solid line.
    is_lasso:   bool = False
    # Universal per-placement colour overrides (apply to controls).
    # When None, the placement's component falls back to theme colour.
    color_fill:   Color | None = None    # body / background
    color_text:   Color | None = None    # caption / label / digits
    color_accent: Color | None = None    # active state (toggle on, slider knob, …)
    color_track:  Color | None = None    # track of slider / progress / toggle
    # PBR material parameters. Used by the PBRSphere kind; any other kind
    # can also use them to render with a PBR look via "PBR shading" toggle.
    pbr_preset:    str   = ""
    pbr_metallic:  float = 0.0
    pbr_roughness: float = 0.4
    pbr_specular:  float = 0.5
    pbr_clearcoat: float = 0.0
    pbr_clearcoat_roughness: float = 0.05
    pbr_emissive:  Color | None = None
    pbr_use_color_fill: bool = True       # use color_fill as base; else (0.85, 0.10, 0.18)
    # PBR texture slots — paths to images bound to material maps. Live
    # Mesh3D/PBRSphere render uses them via render_mesh's albedo /
    # metallic_rough / normal / ao / emissive samplers.
    pbr_albedo_map:         str = ""
    pbr_metallic_rough_map: str = ""
    pbr_normal_map:         str = ""
    pbr_ao_map:             str = ""
    pbr_emissive_map:       str = ""
    # 3-D mesh fields (for kind == "Mesh3D").
    mesh_kind:       str  = "Sphere"      # one of MESH_LIBRARY keys
                                          # (no procedural butterfly — load .3ds
                                          # via mesh.import_3d / File → Import 3D)
    mesh_wireframe:  bool = False
    # Cyclic wing flap — when > 0, mesh_flap is auto-driven by the
    # play clock with amplitude ±mesh_flap_amp radians at this freq
    # (Hz). The Designer's render-cache key uses quantized mesh_flap
    # so the cycle reuses ~8 pre-rendered frames.
    mesh_flap_freq:  float = 0.0
    mesh_flap_amp:   float = 0.6
    # When False, this placement does NOT participate in the global
    # state-cycle Play loop. Its `current_state` is set explicitly
    # (e.g. by tool call or runtime code-behind) and only the tween
    # toward that state runs. Cyclic mesh-flap still updates.
    cycle_states:    bool  = True
    mesh_yaw:        float = 0.4          # radians (rotate around Y axis)
    mesh_pitch:      float = 0.25         # radians (rotate around X axis)
    mesh_roll:       float = 0.0          # radians (rotate around Z axis / view axis)
    # Camera distance from the mesh origin (in world units). Default of
    # 3.5 fits a unit-radius sphere; imported meshes normalised to a
    # span of ~1.0 want a closer ~1.2.
    mesh_dist:       float = 3.5
    # Some imported models (notably the butterfly.3ds in examples/) are
    # authored head-down relative to our renderer's Y axis. Toggle this
    # to vertically flip the rendered output without touching the
    # underlying geometry, UVs, or face winding.
    mesh_flip_y:     bool  = False
    # Per-sub-mesh albedo textures, keyed by the part name reported by
    # the loader (e.g. "Wing_Right", "Wing_Left", "Body" for the .3ds
    # butterfly). When non-empty, the renderer builds one Material per
    # part and assigns face_mats from `vert_part_ids` so each section
    # samples its own texture. Falls back to `pbr_albedo_map` / `texture_path`
    # for parts not listed here.
    mesh_part_textures: dict = field(default_factory=dict)
    mesh_flap:       float = 0.0          # butterfly-only "flap" param
    # Texture-fill (paint a tileable image across the placement bbox).
    texture_path:    str   = ""
    texture_scale:   float = 1.0
    texture_offset_x: float = 0.0
    texture_offset_y: float = 0.0
    texture_rotation: float = 0.0          # degrees
    texture_tint:    Color | None = None
    texture_blend:   str   = "normal"      # normal / multiply / overlay / screen
    # Multi-layer texture stack. When non-empty, takes precedence over the
    # single-texture fields above. Layers compose bottom-up.
    texture_layers:  list[dict] = field(default_factory=list)

    # ------------------------------------------------------------------
    # Maya-parity foundations (Phase 0)
    # ------------------------------------------------------------------
    # `view_mode` selects how a Mesh3D placement is rendered in the
    # canvas: "wireframe" (4), "shaded" (5), "textured" (6), "lit" (7,
    # default), "wire_on_shaded" (Alt+5), "xray". `_mesh_render_bytes`
    # reads this to pick `wireframe=` / `transparent_bg=` / alpha for
    # the path-traced output. Non-Mesh3D placements ignore it.
    view_mode:       str   = "lit"
    # Pivot point (used by Rotate / Scale tools). Stored as a normalised
    # offset in [0, 1] of the placement bbox so the pivot survives
    # resize. Defaults to centre (0.5, 0.5). Maya's "D-drag pivot edit"
    # mutates these in place; the rotate gizmo + scale handles read
    # them to choose the rotation/scale origin.
    pivot_x_norm:    float = 0.5
    pivot_y_norm:    float = 0.5
    # Parenting (G4 Phase 7d). When non-None, this placement is a
    # CHILD of `parent_name` (matched by `Placement.name`). Position
    # is interpreted RELATIVE to the parent — when the parent moves,
    # children move with it. Cycles are guarded against in the world-
    # offset walker (`_world_offset_for`). Name-based matching (rather
    # than index) survives Outliner reordering + serialisation
    # cleanly.
    parent_name:     str | None = None
    # G7 Phase 13 — NURBS curve control points (kind == "NURBSCurve").
    # Stored in placement-local coords (0..p.w, 0..p.h) so the curve
    # scales with the placement bbox. v1 uses a Catmull-Rom spline
    # interpolation through every control point; future phases will
    # add proper NURBS weights + knot vectors.
    nurbs_points:    list[tuple[float, float]] = field(default_factory=list)
    nurbs_closed:    bool = False
    # G8 Phase 16 — Construction History DAG. A list of op records in
    # chronological order. Each record:
    #   { "op": "Loft" | "Group" | "Transfer Texture" | "Set Key" | ... ,
    #     "t": <anim_clock_t at op time>,
    #     "params": {...},
    #     "summary": "<short user-facing description>" }
    # Future phases will materialise this as a proper DAG with input
    # links + the ability to replay / re-evaluate an op with new
    # params (Maya's "input connections" panel). For v1 the field is
    # an append-only log; the Channel Box "History" tab renders it.
    history:         list[dict] = field(default_factory=list)

    # Animation states. Index 0 is always treated as the rest pose.
    states: list[AnimState] = field(default_factory=lambda: [AnimState("default")])
    current_state: int = 0
    # Click trigger: when this placement is clicked in Preview, switch
    # placement named `on_click_target` between state 0 and `on_click_state`.
    on_click_target: str = ""
    on_click_state:  int = 1
    # Runtime (not persisted) — smoothly interpolated transform.
    _t_dx:       float = field(default=0.0, init=False, repr=False)
    _t_dy:       float = field(default=0.0, init=False, repr=False)
    _t_scale:    float = field(default=1.0, init=False, repr=False)
    _t_opacity:  float = field(default=1.0, init=False, repr=False)
    _t_rotation: float = field(default=0.0, init=False, repr=False)

    def to_json(self) -> dict:
        d = {
            "kind": self.kind, "x": self.x, "y": self.y,
            "w": self.w, "h": self.h, "name": self.name,
            "props": self.props,
            "shape": self.shape, "points": self.points,
            "path_d": self.path_d,
            "fill": list(self.fill), "stroke": list(self.stroke),
            "stroke_w": self.stroke_w,
            "image_path": self.image_path,
            "states": [s.to_json() for s in self.states],
            "current_state": self.current_state,
            "on_click_target": self.on_click_target,
            "on_click_state": self.on_click_state,
            "is_hotspot": self.is_hotspot,
        }
        if self.color_fill   is not None: d["color_fill"]   = list(self.color_fill)
        if self.color_text   is not None: d["color_text"]   = list(self.color_text)
        if self.color_accent is not None: d["color_accent"] = list(self.color_accent)
        if self.color_track  is not None: d["color_track"]  = list(self.color_track)
        if self.pbr_preset:
            d["pbr_preset"] = self.pbr_preset
        d["pbr"] = {
            "metallic": self.pbr_metallic, "roughness": self.pbr_roughness,
            "specular": self.pbr_specular, "clearcoat": self.pbr_clearcoat,
            "clearcoat_roughness": self.pbr_clearcoat_roughness,
            "use_color_fill": self.pbr_use_color_fill,
        }
        if self.pbr_emissive is not None:
            d["pbr"]["emissive"] = list(self.pbr_emissive)
        maps = {k: getattr(self, "pbr_" + k + "_map")
                for k in ("albedo", "metallic_rough", "normal", "ao", "emissive")
                if getattr(self, "pbr_" + k + "_map", "")}
        if maps:
            d["pbr_maps"] = maps
        d["mesh"] = {
            "kind": self.mesh_kind, "wireframe": self.mesh_wireframe,
            "yaw": self.mesh_yaw, "pitch": self.mesh_pitch, "flap": self.mesh_flap,
            "flap_freq": self.mesh_flap_freq, "flap_amp": self.mesh_flap_amp,
            "dist": self.mesh_dist,
            "flip_y": self.mesh_flip_y,
            "roll": getattr(self, "mesh_roll", 0.0),
            "part_textures": dict(getattr(self, "mesh_part_textures", {}) or {}),
            "view_mode": getattr(self, "view_mode", "lit"),
        }
        # Pivot (Phase 0): only emit when non-default so older layouts
        # round-trip unchanged.
        _px = getattr(self, "pivot_x_norm", 0.5)
        _py = getattr(self, "pivot_y_norm", 0.5)
        if abs(_px - 0.5) > 1e-6 or abs(_py - 0.5) > 1e-6:
            d["pivot"] = [_px, _py]
        # Parent name (Phase 7d) — only emit when set so loose / un-
        # parented placements stay clean.
        if getattr(self, "parent_name", None):
            d["parent_name"] = self.parent_name
        # NURBS curve (Phase 13) — only emit for NURBSCurve placements
        # so non-curve kinds don't bloat the save file.
        if self.kind == "NURBSCurve" or getattr(self, "nurbs_points", None):
            d["nurbs_points"] = [list(p) for p in (self.nurbs_points or [])]
            d["nurbs_closed"] = bool(getattr(self, "nurbs_closed", False))
        # Construction history (Phase 16) — only emit when present so
        # untouched placements stay small.
        if getattr(self, "history", None):
            d["history"] = list(self.history)
        d["cycle_states"] = self.cycle_states
        if self.texture_path:
            d["texture"] = {
                "path": self.texture_path, "scale": self.texture_scale,
                "offset_x": self.texture_offset_x, "offset_y": self.texture_offset_y,
                "rotation": self.texture_rotation, "blend": self.texture_blend,
            }
            if self.texture_tint is not None:
                d["texture"]["tint"] = list(self.texture_tint)
        if self.texture_layers:
            d["texture_layers"] = list(self.texture_layers)
        d_out = d  # keep for json
        if self.gradient_end is not None:
            d["gradient_end"] = list(self.gradient_end)
        d["gradient_angle"] = self.gradient_angle
        return d

    @classmethod
    def from_json(cls, d: dict) -> "Placement":
        ge = d.get("gradient_end")
        states = [AnimState.from_json(s) for s in d.get("states", [])]
        if not states:
            states = [AnimState("default")]
        return cls(
            kind=d["kind"], x=d["x"], y=d["y"], w=d["w"], h=d["h"],
            name=d.get("name", ""), props=d.get("props", {}),
            shape=d.get("shape", ""),
            points=[tuple(p) for p in d.get("points", [])],
            path_d=d.get("path_d", ""),
            fill=tuple(d.get("fill", [122, 88, 244, 255])),
            stroke=tuple(d.get("stroke", [0, 0, 0, 0])),
            stroke_w=d.get("stroke_w", 1.5),
            gradient_end=tuple(ge) if ge else None,
            gradient_angle=d.get("gradient_angle", 90.0),
            image_path=d.get("image_path", ""),
            states=states,
            current_state=d.get("current_state", 0),
            on_click_target=d.get("on_click_target", ""),
            on_click_state=d.get("on_click_state", 1),
            is_hotspot=d.get("is_hotspot", False),
            color_fill  =tuple(d["color_fill"])   if d.get("color_fill")   else None,
            color_text  =tuple(d["color_text"])   if d.get("color_text")   else None,
            color_accent=tuple(d["color_accent"]) if d.get("color_accent") else None,
            color_track =tuple(d["color_track"])  if d.get("color_track")  else None,
            pbr_preset=d.get("pbr_preset", ""),
            pbr_metallic =d.get("pbr", {}).get("metallic", 0.0),
            pbr_roughness=d.get("pbr", {}).get("roughness", 0.4),
            pbr_specular =d.get("pbr", {}).get("specular", 0.5),
            pbr_clearcoat=d.get("pbr", {}).get("clearcoat", 0.0),
            pbr_clearcoat_roughness=d.get("pbr", {}).get("clearcoat_roughness", 0.05),
            pbr_emissive=tuple(d["pbr"]["emissive"]) if d.get("pbr", {}).get("emissive") else None,
            pbr_use_color_fill=d.get("pbr", {}).get("use_color_fill", True),
            pbr_albedo_map        =d.get("pbr_maps", {}).get("albedo", ""),
            pbr_metallic_rough_map=d.get("pbr_maps", {}).get("metallic_rough", ""),
            pbr_normal_map        =d.get("pbr_maps", {}).get("normal", ""),
            pbr_ao_map            =d.get("pbr_maps", {}).get("ao", ""),
            pbr_emissive_map      =d.get("pbr_maps", {}).get("emissive", ""),
            mesh_kind     =d.get("mesh", {}).get("kind", "Sphere"),
            mesh_wireframe=d.get("mesh", {}).get("wireframe", False),
            mesh_yaw      =d.get("mesh", {}).get("yaw", 0.4),
            mesh_pitch    =d.get("mesh", {}).get("pitch", 0.25),
            mesh_flap     =d.get("mesh", {}).get("flap", 0.0),
            mesh_flap_freq=d.get("mesh", {}).get("flap_freq", 0.0),
            mesh_flap_amp =d.get("mesh", {}).get("flap_amp", 0.6),
            mesh_dist     =d.get("mesh", {}).get("dist", 3.5),
            mesh_flip_y   =d.get("mesh", {}).get("flip_y", False),
            mesh_roll     =d.get("mesh", {}).get("roll", 0.0),
            mesh_part_textures=dict(d.get("mesh", {}).get("part_textures", {}) or {}),
            view_mode     =d.get("mesh", {}).get("view_mode", "lit"),
            pivot_x_norm  =(d.get("pivot") or [0.5, 0.5])[0],
            pivot_y_norm  =(d.get("pivot") or [0.5, 0.5])[1],
            parent_name   =d.get("parent_name") or None,
            nurbs_points  =[tuple(p) for p in d.get("nurbs_points", [])],
            nurbs_closed  =bool(d.get("nurbs_closed", False)),
            history       =list(d.get("history", [])),
            cycle_states  =d.get("cycle_states", True),
            texture_path     =d.get("texture", {}).get("path", ""),
            texture_scale    =d.get("texture", {}).get("scale", 1.0),
            texture_offset_x =d.get("texture", {}).get("offset_x", 0.0),
            texture_offset_y =d.get("texture", {}).get("offset_y", 0.0),
            texture_rotation =d.get("texture", {}).get("rotation", 0.0),
            texture_blend    =d.get("texture", {}).get("blend", "normal"),
            texture_tint=tuple(d["texture"]["tint"]) if d.get("texture", {}).get("tint") else None,
            texture_layers=list(d.get("texture_layers", [])),
        )


@dataclass
class AppWindow:
    name:    str = "MainWindow"
    title:   str = "App Window"
    w:       float = 800
    h:       float = 600
    shape:   str = "rect"        # "rect" | "ellipse" | "path"
    path_d:  str = ""
    bg_color: Color = (250, 250, 252, 255)
    gradient_end: Color | None = None
    gradient_angle: float = 90.0
    border_radius: float = 8
    transparent:   bool = False
    show_title_bar: bool = True
    title_bar_color: Color | None = None         # falls back to theme.primary
    title_bar_color_end: Color | None = None     # second gradient stop
    # Lighting studio applied to all PBR / Mesh3D renders in this window.
    studio: str = "Default Soft Studio"
    # "referenced" → texture_path stays an absolute fs path (small .esk).
    # "embedded" → on save, all referenced textures + paint masks are
    # copied into <skin>/assets/ and rewritten to relative paths.
    texture_export_mode: str = "referenced"
    # Python source paired with this skin — used by Code Link to jump to
    # handlers when the user double-clicks a placement in the Designer.
    code_file: str = ""

    def to_json(self) -> dict:
        d = {**self.__dict__,
             "bg_color": list(self.bg_color)}
        if self.gradient_end is not None:
            d["gradient_end"] = list(self.gradient_end)
        d["gradient_angle"] = self.gradient_angle
        if self.title_bar_color is not None:
            d["title_bar_color"] = list(self.title_bar_color)
        if self.title_bar_color_end is not None:
            d["title_bar_color_end"] = list(self.title_bar_color_end)
        d["studio"] = self.studio
        return d

    @classmethod
    def from_json(cls, d: dict) -> "AppWindow":
        ge = d.get("gradient_end")
        tb1 = d.get("title_bar_color")
        tb2 = d.get("title_bar_color_end")
        return cls(
            name=d.get("name", "MainWindow"),
            title=d.get("title", "App Window"),
            w=d.get("w", 800), h=d.get("h", 600),
            shape=d.get("shape", "rect"),
            path_d=d.get("path_d", ""),
            bg_color=tuple(d.get("bg_color", [250, 250, 252, 255])),
            gradient_end=tuple(ge) if ge else None,
            gradient_angle=d.get("gradient_angle", 90.0),
            border_radius=d.get("border_radius", 8),
            transparent=d.get("transparent", False),
            show_title_bar=d.get("show_title_bar", True),
            title_bar_color=tuple(tb1) if tb1 else None,
            title_bar_color_end=tuple(tb2) if tb2 else None,
            studio=d.get("studio", "Default Soft Studio"),
            texture_export_mode=d.get("texture_export_mode", "referenced"),
            code_file=d.get("code_file", ""),
        )


def snap(v: float, enabled: bool = True) -> float:
    return round(v / GRID) * GRID if enabled else v


# --- Factory --------------------------------------------------------------

def _make(kind: str, x: float, y: float, w: float, h: float, props: dict) -> ui.Component:
    if kind == "Button":
        return ui.Button(x=x, y=y, w=w, h=h, label=props.get("label", "Button"),
                         variant=props.get("variant", "solid"))
    if kind == "Card":
        return ui.Card(x=x, y=y, w=w, h=h, elevation=props.get("elevation", "medium"))
    if kind == "Toggle":
        return ui.Toggle(x=x, y=y, w=w, h=h, value=props.get("value", False))
    if kind == "Slider":
        return ui.Slider(x=x, y=y, w=w, h=h, value=props.get("value", 0.5))
    if kind == "Checkbox":
        return ui.Checkbox(x=x, y=y, w=w, h=h, value=props.get("value", False),
                           label=props.get("label", "Option"))
    if kind == "Radio":
        return ui.Radio(x=x, y=y, w=w, h=h, value=props.get("value", False),
                        label=props.get("label", "Option"))
    if kind == "Label":
        return ui.Label(x=x, y=y, w=w, h=h, text=props.get("label", "Label"), size=14)
    if kind == "Badge":
        return ui.Badge(x=x, y=y, w=w, h=h, text=props.get("label", "NEW"),
                        variant=props.get("variant", "primary"))
    if kind == "Progress":
        return ui.ProgressBar(x=x, y=y, w=w, h=h, value=props.get("value", 0.6))
    if kind == "Divider":
        return ui.Divider(x=x, y=y, w=w, h=h)
    if kind == "Chip":
        return ui.Chip(x=x, y=y, w=w, h=h, label=props.get("label", "tag"))
    if kind == "TextField":
        return ui.TextField(x=x, y=y, w=w, h=h, placeholder=props.get("label", "Type…"))
    if kind == "Avatar":
        return ui.Avatar(x=x, y=y, w=w, h=h, initial=props.get("label", "A"))
    raise KeyError(kind)


# --- Path helpers ---------------------------------------------------------

def _rect_d(x, y, w, h) -> str:
    return f"M {x} {y} L {x+w} {y} L {x+w} {y+h} L {x} {y+h} Z"


# Keep the historical path (~/.elysium/designer-prefs.json) so existing
# installs are picked up, but route I/O through the framework Settings API
# (atomic writes, shared abstraction) instead of hand-rolled JSON.
_DESIGNER_PREFS_PATH = (Path.home() / ".elysium" / "designer-prefs.json")


def _designer_settings():
    from elysium.settings import Settings
    return Settings("designer", path=_DESIGNER_PREFS_PATH)


def _load_designer_prefs() -> dict:
    # The Designer mutates a plain dict then calls save, so hand back the raw
    # contents; persistence + atomic write live in Settings.
    return dict(_designer_settings()._data)


def _save_designer_prefs(prefs: dict) -> None:
    s = _designer_settings()
    s._data = dict(prefs)
    s.save()


def _hit(rect: tuple[float, float, float, float], mx: float, my: float) -> bool:
    x, y, w, h = rect
    return x <= mx <= x + w and y <= my <= y + h


def _wrap(text: str, width: int = 60) -> list[str]:
    """Word-wrap a string to ``width`` chars. Multi-line input handled."""
    lines: list[str] = []
    for paragraph in (text or "").splitlines() or [""]:
        cur = ""
        for word in paragraph.split(" "):
            if not cur:
                cur = word
            elif len(cur) + 1 + len(word) <= width:
                cur += " " + word
            else:
                lines.append(cur); cur = word
        if cur: lines.append(cur)
    return lines or [""]


def _short(v) -> str:
    import json
    try: s = json.dumps(v, default=str)
    except Exception: s = str(v)
    return s if len(s) <= 70 else s[:67] + "…"


def _rect(x, y, w, h) -> str:
    return _rect_d(x, y, w, h)


def _round(x, y, w, h, r) -> str:
    r = max(0.0, min(r, w / 2.0, h / 2.0))
    return (
        f"M {x + r} {y} "
        f"L {x + w - r} {y} Q {x + w} {y} {x + w} {y + r} "
        f"L {x + w} {y + h - r} Q {x + w} {y + h} {x + w - r} {y + h} "
        f"L {x + r} {y + h} Q {x} {y + h} {x} {y + h - r} "
        f"L {x} {y + r} Q {x} {y} {x + r} {y} Z"
    )


def _round_top(x, y, w, h, r) -> str:
    return (
        f"M {x + r} {y} "
        f"L {x + w - r} {y} Q {x + w} {y} {x + w} {y + r} "
        f"L {x + w} {y + h} L {x} {y + h} L {x} {y + r} "
        f"Q {x} {y} {x + r} {y} Z"
    )


def _round_bottom(x, y, w, h, r) -> str:
    """Mirror of `_round_top`: square top corners, rounded bottom.
    Used by the status bar so the chrome's rounded bottom corners
    are not painted over by the bar's rectangular background."""
    r = max(0.0, min(r, w / 2.0, h / 2.0))
    return (
        f"M {x} {y} "
        f"L {x + w} {y} L {x + w} {y + h - r} "
        f"Q {x + w} {y + h} {x + w - r} {y + h} "
        f"L {x + r} {y + h} Q {x} {y + h} {x} {y + h - r} "
        f"L {x} {y} Z"
    )


def _ellipse_d(cx, cy, rx, ry) -> str:
    return (
        f"M {cx - rx} {cy} "
        f"a {rx} {ry} 0 1 0 {2*rx} 0 "
        f"a {rx} {ry} 0 1 0 {-2*rx} 0 Z"
    )


def _a11y_role(kind: str) -> str:
    return {
        "Button": "button", "Label": "label", "TextField": "textbox",
        "Checkbox": "checkbox", "Radio": "radio", "Toggle": "switch",
        "Slider": "slider", "Progress": "progressbar",
        "Card": "group", "Image": "img", "Shape": "graphic",
        "Badge": "status", "Chip": "button", "Divider": "separator",
        "Avatar": "img",
    }.get(kind, "generic")


def _shape_path_d_offset(p: Placement, dx: float, dy: float) -> str:
    """Same as `shape_path_d`, but renders with (x, y) translated by (dx, dy)
    without reconstructing the Placement (which is unsafe — Placement has
    init=False runtime fields)."""
    if p.shape == "rect":
        return _rect_d(p.x + dx, p.y + dy, p.w, p.h)
    if p.shape == "ellipse":
        cx = p.x + dx + p.w / 2
        cy = p.y + dy + p.h / 2
        return _ellipse_d(cx, cy, p.w / 2, p.h / 2)
    if p.shape == "line":
        return f"M {p.x + dx} {p.y + dy} L {p.x + dx + p.w} {p.y + dy + p.h}"
    if p.shape == "polygon" and p.points:
        pts = [(px + dx, py + dy) for px, py in p.points]
        d = f"M {pts[0][0]} {pts[0][1]}"
        for px, py in pts[1:]:
            d += f" L {px} {py}"
        return d + " Z"
    if p.shape == "path":
        return p.path_d
    return ""


def _translate_svg_d(d: str, dx: float, dy: float) -> str:
    """Translate every coordinate pair in an SVG `d` string by (dx, dy).

    Only handles the M/L/Q/C/Z command set we emit (no relative-coord
    commands, no arcs). Used at .esk import time so path placements
    visually move with their owning bbox shift — the Designer's path
    renderer ignores Placement.(x, y) for `shape="path"` placements
    (see `shape_path_d` below) so the coordinates have to live in the
    `d` itself."""
    import re as _re
    out: list[str] = []
    # Split on whitespace; tokens are either single letters (commands)
    # or numbers. We pair consecutive numbers as (x, y) and translate
    # each pair. Single trailing numbers (shouldn't occur in our
    # generator) pass through untouched.
    tokens = _re.findall(r"[A-Za-z]|-?\d+(?:\.\d+)?", d)
    i = 0
    while i < len(tokens):
        tok = tokens[i]
        if tok.isalpha():
            out.append(tok)
            i += 1
            continue
        # Number — try to pair with next.
        if i + 1 < len(tokens) and not tokens[i + 1].isalpha():
            try:
                x = float(tok) + dx
                y = float(tokens[i + 1]) + dy
                out.append(f"{x:g}")
                out.append(f"{y:g}")
                i += 2
                continue
            except ValueError:
                pass
        out.append(tok)
        i += 1
    return " ".join(out)


def shape_path_d(p: Placement) -> str:
    if p.shape == "rect":
        return _rect_d(p.x, p.y, p.w, p.h)
    if p.shape == "ellipse":
        cx, cy = p.x + p.w / 2, p.y + p.h / 2
        return _ellipse_d(cx, cy, p.w / 2, p.h / 2)
    if p.shape == "line":
        return f"M {p.x} {p.y} L {p.x + p.w} {p.y + p.h}"
    if p.shape == "polygon" and p.points:
        d = f"M {p.points[0][0]} {p.points[0][1]}"
        for px, py in p.points[1:]:
            d += f" L {px} {py}"
        return d + " Z"
    if p.shape == "path":
        return p.path_d
    return ""


def _path_bbox(d: str) -> tuple[float, float, float, float] | None:
    """Accurate bbox of an SVG path via Skia's path-bounds binding."""
    try:
        x, y, w, h = _n.path_bounds(d)
        return x, y, w, h
    except Exception:
        return None


def bbox_points(points: list[tuple[float, float]]) -> tuple[float, float, float, float]:
    if not points:
        return 0, 0, 0, 0
    xs = [p[0] for p in points]; ys = [p[1] for p in points]
    return min(xs), min(ys), max(xs) - min(xs), max(ys) - min(ys)


def _gradient_endpoints(x: float, y: float, w: float, h: float, angle_deg: float
                        ) -> tuple[tuple[float, float], tuple[float, float]]:
    """Endpoints for a linear gradient across the bbox along `angle_deg`
    (0 = left→right, 90 = top→bottom)."""
    rad = math.radians(angle_deg)
    cx, cy = x + w / 2, y + h / 2
    # Half-extent along the gradient axis = projection of bbox onto the axis.
    half = (abs(math.cos(rad)) * w + abs(math.sin(rad)) * h) / 2
    dx, dy = math.cos(rad) * half, math.sin(rad) * half
    return (cx - dx, cy - dy), (cx + dx, cy + dy)


def _shade(t, amount: float):
    return themes.lighten(t.surface, amount if not t.is_dark else amount * 0.9)


def _handle_positions(x, y, w, h):
    cx = x + w / 2; cy = y + h / 2
    return [(x, y), (cx, y), (x + w, y),
            (x, cy),         (x + w, cy),
            (x, y + h), (cx, y + h), (x + w, y + h)]


