# --- Dock / Taskbar animator ----------------------------------------------


class IconFlapper:
    """Plays the 12-frame wing-flap on the running app's Dock / Taskbar
    icon and restores the static icon when done.

    State machine:
      idle  -> play() -> playing -> (last frame swapped) -> idle

    `play()` while already playing is a NO-OP — the user got their
    flap and won't get another until the current one finishes. This
    is what gives the "flap once per event, no repeat" property.
    """

    FPS: float = 24.0

    def __init__(self, designer: "Designer") -> None:
        self.designer = designer
        self.frames: list[bytes] = []
        self.static_icon: bytes = b""
        self._playing = False
        self._start_t = 0.0
        self._last_frame_set = -1
        self._load_assets()

    def _asset_root(self) -> Path:
        """Locate the assets dir. When PyInstaller-bundled, the
        frames live under `sys._MEIPASS/elysium-designer/assets/flap`;
        in source checkouts, they live next to __main__.py."""
        meipass = getattr(sys, "_MEIPASS", None)
        if meipass:
            cand = Path(meipass) / "elysium-designer" / "assets"
            if (cand / "flap").is_dir():
                return cand
        return Path(__file__).resolve().parent / "assets"

    def _load_assets(self) -> None:
        root = self._asset_root()
        static = root / "ElysiumDesigner.png"
        if static.is_file():
            self.static_icon = static.read_bytes()
        flap_dir = root / "flap"
        if not flap_dir.is_dir():
            return
        for p in sorted(flap_dir.glob("*.png")):
            try:
                self.frames.append(p.read_bytes())
            except Exception:
                continue

    def play(self) -> None:
        """Start a one-shot flap if one isn't already in flight."""
        if self._playing or not self.frames:
            return
        self._playing = True
        self._start_t = time.monotonic()
        self._last_frame_set = -1

    def tick(self) -> None:
        """Called from on_frame. Cheap when idle (single bool check)."""
        if not self._playing:
            return
        now = time.monotonic()
        elapsed = now - self._start_t
        idx = int(elapsed * self.FPS)
        if idx >= len(self.frames):
            # Finished — restore the static icon and go idle.
            if self.static_icon:
                _set_dock_icon(self.static_icon)
            self._playing = False
            self._last_frame_set = -1
            return
        if idx != self._last_frame_set:
            _set_dock_icon(self.frames[idx])
            self._last_frame_set = idx


def _set_dock_icon(png_bytes: bytes) -> None:
    """Module-level helper so we can lazy-import elysium.dock + swallow
    errors silently — a failed swap must never break the render
    loop."""
    try:
        from elysium.dock import set_app_icon_from_png
        set_app_icon_from_png(png_bytes)
    except Exception:
        pass


# --- Designer --------------------------------------------------------------

class Designer:
    def __init__(self, skin_path: Path) -> None:
        self.skin_path = skin_path.resolve()
        self.doc_path = self.skin_path / "designer_layout.json"
        # Click-target rect for the App Window "Kind" property dropdown
        # (Application ↔ Component). Populated each frame in
        # `_paint_property_row`; consumed by `_handle_property_click`.
        self._skin_kind_row_rect: tuple[float, float, float, float] | None = None
        # Per-item click rects of the open dropdown (kind, rect). Empty
        # when the dropdown is closed.
        self._skin_kind_dropdown_rects: list[tuple[str, tuple[float, float, float, float]]] = []
        self._skin_kind_dropdown_open: bool = False

        self.app = ely.App(title=f"Elysium Designer — {self.skin_path.name}",
                           identifier="dev.elysium.designer")
        # Restore last window size + position from prefs (per-user, not
        # per-skin) so reopening the Designer lands exactly where it
        # was. Auto-saved by the on_frame persistence tick.
        global WIDTH, HEIGHT
        prefs = _load_designer_prefs()
        init_w, init_h = prefs.get("size", (WIDTH, HEIGHT))
        # Title-bar pin state — when True the auto-hide tween is
        # suppressed and the strip stays fully visible. Default off
        # (matches the user-feedback request: auto-hide by default,
        # pin to override). Persisted in _designer_prefs across runs.
        self.title_pinned: bool = bool(prefs.get("title_pinned", False))
        # Smoothed [0, 1] visibility for the title strip — 1 = fully
        # visible, 0 = fully off-screen. Tweened toward `_title_target`
        # each frame.
        self._title_visible: float = 1.0
        self._title_target:  float = 1.0
        # Self-host migration: the Designer's OWN host window is
        # FULLY borderless  transparent + no native title bar
        # so every pixel of chrome is Elysium-styled. Drag, close,
        # and the custom title-strip traffic lights are all painted
        # + dispatched by the Designer itself (see `_paint_title_strip`
        # and the title-strip drag dispatch in `on_frame`).
        self.win = self.app.window(transparent=True, title_bar=False,
                                   resizable=True,
                                   initial_size=(int(init_w), int(init_h)))
        # Drop the OS-rectangular drop-shadow so it doesn't reveal the
        # window's rect bounding box around the painted rounded body.
        # We paint our own layered shadow in `_paint` that follows the
        # rounded path  the result is "free-floating glossy slab"
        # rather than "rounded paint inside a rect frame".
        try:
            self.win.set_has_shadow(False)
        except Exception:
            pass
        if "pos" in prefs:
            try:
                px, py = prefs["pos"]
                # Skip (0, 0) — it's the sentinel the native side returns
                # before any Moved event has fired. Restoring to (0,0)
                # would jam the window into the top-left corner.
                if (int(px), int(py)) != (0, 0):
                    self.win.set_outer_position(int(px), int(py))
            except Exception: pass
        # Apply restored size to the module-level constants so the
        # first frame doesn't paint at the default before our on_frame
        # surface_size sync kicks in.
        WIDTH, HEIGHT = int(init_w), int(init_h)
        self._last_persist_t = 0.0
        self._last_persisted_geo = None

        # Self-host scaffolding (Stage 3a). Loads the empty chrome
        # `.esk` so the Designer window has a skin attached; the
        # hand-rolled `_paint_*` chrome still runs and `on_frame`'s
        # `publish_display_list` covers the empty scene each frame.
        # Gated behind `ELYSIUM_DESIGNER_CHROME_SKIN` until Stage 3b
        # authors the first real surface into the skin. Failures are
        # logged but never block startup.
        if os.environ.get("ELYSIUM_DESIGNER_CHROME_SKIN") == "1":
            chrome_path = Path(__file__).parent / "designer-chrome.esk"
            try:
                self.win.load_skin(str(chrome_path))
                print(f"[chrome-skin] loaded {chrome_path}",
                      file=sys.stderr, flush=True)
            except Exception as exc:
                print(f"[chrome-skin] load failed: {exc}",
                      file=sys.stderr, flush=True)
        # Periodic auto-save of the skin so an unexpected crash / kill never
        # loses more than ~auto_save_interval seconds of work. Set to 0 to
        # disable. The tick runs in on_frame and uses save_layout(), the
        # same code path File → Save uses.
        self._last_auto_save_t  = time.time()
        self._auto_save_interval: float = 15.0

        # Theme.
        self.theme_index = reactive.signal(0)
        self.themes_list = [themes.light, themes.dark, themes.oled,
                            themes.midnight_glass, themes.frost]

        # Document.
        self.window_doc = AppWindow(bg_color=(250, 250, 252, 255))
        self.placements: list[Placement] = []
        # Selection: ("window", {-1}) | ("placement", set_of_indices) | ("none", set())
        self.sel_kind: str = "none"
        self.sel_idx: int = -1
        self.sel_set: set[int] = set()        # multi-select
        self.hover_idx: int = -1
        self._name_counters: dict[str, int] = {}

        # Undo / redo command stack (snapshots of doc state).
        self._undo_stack: list[dict] = []
        self._redo_stack: list[dict] = []
        self._undo_limit: int = 100

        # Canvas zoom — visual zoom of the form area (window mockup +
        # placements). Cmd+= / Cmd+- / Cmd+0 from the keyboard, and pinch
        # gestures from the trackpad, drive this. 1.0 = 100% (native pixels).
        self.canvas_zoom: float = 1.0
        self.canvas_zoom_min: float = 0.25
        self.canvas_zoom_max: float = 6.0
        # When True, the App Window doc auto-fits the form area on
        # every Designer-window resize. Flips off the moment the user
        # manually zooms or pans so an intentional zoom level survives
        # subsequent resizes. Re-enable via View ▸ Fit Canvas to Window.
        self.canvas_auto_fit: bool = True
        # Canvas pan offset (form-area pixels). Drag with Hand tool or
        # space-held to update.
        self.canvas_pan_x: float = 0.0
        self.canvas_pan_y: float = 0.0
        self._pan_drag_start: tuple[float, float] | None = None
        self._space_held: bool = False

        # Resize handle drag state.
        self.resize_handle: int = -1            # 0..7 if dragging a handle
        self.resize_start_rect: tuple[float, float, float, float] = (0, 0, 0, 0)
        self.resize_start_cur:  tuple[float, float] = (0, 0)

        # Marquee selection drag.
        self.marquee_start: tuple[float, float] | None = None

        # Bezier path editing (post-commit).
        self.editing_anchors_of: int = -1       # placement index whose anchors we're editing
        self.dragging_anchor: int = -1
        self._anchor_cache: list[tuple[float, float]] = []

        # State-canvas editing — selected state index for the focused placement.
        self.editing_state_idx: int = 0         # state being authored (0 = base/rest pose)

        # Component-instance pool — keyed by placement id() so we don't
        # allocate fresh ui.Button/ui.Card/etc every frame.
        self._comp_cache: dict[int, ui.Component] = {}
        self._comp_cache_kind: dict[int, str] = {}

        # Idle-decay state: tracks the last "interesting" frame so the
        # animation thread can drop to ~4 Hz when nothing is going on.
        self._last_busy_t: float = 0.0
        self._anim_clock_t: float = 0.0     # ever-incrementing seconds for marching-ants etc.
        # Hashes of the last frame's state, used for cheap damage tracking.
        self._last_state_hash: int = 0

        # Timeline scrub state. None | ("playhead",) | ("diamond", pi, si).
        self.timeline_drag: tuple | None = None

        # Brush state — per-placement PaintMask keyed by id(placement),
        # plus current brush settings.
        self.paint_masks: dict[int, object] = {}
        self.brush_radius: float = 16.0
        self.brush_opacity: float = 1.0
        self.brush_hardness: float = 0.55
        self.brush_color: tuple[int, int, int, int] = (220, 60, 60, 255)
        # G-Brush Phase B — active engine-backed preset + session
        # overrides. The Tool Properties Dock's sliders write into
        # `brush_params_override`; explicit "Save Preset" persists the
        # change. `brush_recents` is the last-N preset IDs the user
        # actually painted with (most recent first), capped at 32.
        self.active_preset_id: str = "elysium.round.hard"
        self.brush_params_override: dict[str, float] = {}
        self.brush_recents: list[str] = []
        # G-Brush Phase G — Windows touch input. `brush_pressure` is
        # the per-sample pressure (0..1) reported by WM_POINTER on
        # touch-capable hardware; defaults to 1.0 ("full press") so
        # mouse strokes (and any device that doesn't report pressure)
        # produce the preset's baseline params. `brush_velocity` is
        # the normalised stroke speed sampled from cursor-delta /
        # frame-time. Both are consumed by `apply_dynamics()` when
        # the preset has Dynamics curves authored.
        self.brush_pressure: float = 1.0
        self.brush_velocity: float = 0.0
        self._last_brush_t: float = 0.0
        # Optional tileable RGBA brush stamp ("texture slurp" workflow). When
        # set, _brush_apply paints with this tile instead of brush_color.
        self.brush_texture = None                       # np.ndarray | None
        self.brush_texture_name: str = ""
        self.brush_texture_scale: float = 1.0
        # Named palette of saved brush textures (slurped tiles). Kept
        # for backwards compatibility — the new "Textures" strip in the
        # palette panel reads from here.
        self.brush_palette: dict[str, object] = {}
        # Unified palette: one strip of 12 generic slots. Each slot is
        # either None (empty) or a dict carrying its content:
        #
        #   {"kind": "color",   "rgba": (r, g, b, a)}
        #   {"kind": "texture", "name": "wing_tile"}
        #
        # The user explicitly fills, applies, and clears each slot via
        # the popovers (no auto-fill anywhere). Loaded from prefs on
        # launch; saved after every mutation.
        self.palette: list[dict | None] = [None] * 12
        # Tool Properties dock dock / float state. Saved + restored
        # via the process-wide designer prefs file. Mode is "docked"
        # (default  the slider strip pins to the bottom of the form
        # area, the original placement) or "floating" (movable card
        # at `tool_dock_float_pos`). Drag is initiated by pressing
        # the dock's brush chip (which acts as the grip); while
        # `_tool_dock_drag_offset` is non-None the per-frame
        # dispatcher in `on_frame` updates `tool_dock_float_pos` so
        # the dock tracks the cursor.
        try:
            _td_prefs = _load_designer_prefs()
        except Exception:
            _td_prefs = {}
        self.tool_dock_mode: str = str(_td_prefs.get(
            "tool_dock_mode", "docked"))
        if self.tool_dock_mode not in ("docked", "floating"):
            self.tool_dock_mode = "docked"
        _tfp = _td_prefs.get("tool_dock_float_pos")
        self.tool_dock_float_pos: tuple[float, float] | None = (
            (float(_tfp[0]), float(_tfp[1]))
            if isinstance(_tfp, (list, tuple)) and len(_tfp) == 2
            else None)
        self._tool_dock_drag_offset: tuple[float, float] | None = None
        self._tool_dock_drag_just_started: bool = False
        # Custom title-strip drag state. When the user presses inside
        # the drag region of the title strip, `_title_drag_grab` stores
        # the cursor's position INSIDE the window at press time; the
        # per-frame dispatcher then keeps the window's outer position
        # such that the cursor stays at the same window-relative
        # location (so the window follows the cursor without skipping).
        self._title_drag_grab: tuple[float, float] | None = None
        # Pending Aether-driven texture fill: when the user opens the
        # Texture popover's "Generate via Aether..." and the agent
        # later registers a tile in brush_palette, _aether_append_
        # palette_tile drops it into this slot.
        self._pending_texture_slot: int | None = None
        # Pending "Capture from canvas" slot: armed when the user
        # picks "Capture from Image placement" from a Texture popover.
        # The next _commit_eyedrop slurp routes its tile into this
        # slot (and applies it as the active brush). Cancelled by Esc
        # or by opening another popover.
        self._pending_slurp_slot: int | None = None
        # Pending color-picker target slot: set when the user opens the
        # color picker from a slot's Color popover so the confirmation
        # path knows where the chosen color belongs.
        self._pending_color_slot: int | None = None
        # Slot popover state. Only one popover is open at a time. Shape:
        #   {"mode": "color" | "texture",
        #    "slot": int,
        #    "anchor": (x, y),
        #    "items": [...],   # for texture mode: the tile grid
        #    "rects": [...]}   # populated each paint
        self._slot_popover: dict | None = None
        # Hydrate from disk so the user's saved palettes persist.
        try:
            self._load_brush_palettes_from_prefs()
        except Exception:
            pass
        self._last_brush_pos: tuple[float, float] | None = None
        self._brush_dirty: set[int] = set()
        # Rotate-gizmo drag state. ("yaw"|"pitch"|"roll",
        #   start_mouse_x, start_mouse_y, start_angle).
        self._gizmo_drag: tuple | None = None
        self._gizmo_hit_rects: list = []  # rebuilt every paint
        # Camera-distance drag state. (start_mouse_y_screen, start_mesh_dist).
        # Set by the TOOL_CAM_DIST dispatch when the user presses; cleared
        # on release. While set, every frame's pressed cursor delta
        # adjusts the selected Mesh3D's mesh_dist.
        self._cam_dist_drag: tuple | None = None

        # Drag / drawing state.
        self.drag_kind: str | None = None
        self.drag_props: dict = {}
        self.drag_size: tuple[float, float] = (0, 0)
        self.drag_pos:  tuple[float, float] = (0, 0)
        self.move_offset: tuple[float, float] | None = None
        self.tool: str = TOOL_SELECT
        self.draw_start: tuple[float, float] | None = None
        self.draw_current: tuple[float, float] | None = None
        self.pen_points: list[tuple[float, float]] = []
        self.pen_recording: bool = False        # freehand pen drag in progress
        # Bezier-pen state: anchors with outgoing control offsets.
        self.bezier_anchors: list[tuple[float, float, float, float]] = []
        self.bezier_drag: tuple[float, float] | None = None    # current anchor being dragged for handle

        # Mouse edges.
        self._was_pressed: bool = False
        self._press_count: int = 0
        # First on_frame snapshot is recorded lazily so the very first
        # frame doesn't see a phantom right-click. See on_frame.
        self._right_press_count: int | None = None

        # UI state.
        self.prop_tab = reactive.signal(0)
        # Properties pane Accordion sections (spec §9 Stage 3e). Each
        # section header in the "Categorized" tab is a clickable
        # row that toggles its body's expand state. Default: all open.
        self.props_section_open: dict[str, bool] = {}
        self._prop_section_rects: list[
            tuple[str, tuple[float, float, float, float]]] = []
        self.menu_open: str | None = None
        # Active menu set (Maya F2–F6 parity, Phase 0b). Switches which
        # 3-tuple-tagged menu items are visible. Drives — and is driven
        # by — the upcoming Status-Line "Modeling ▾" dropdown.
        self.menu_set: str = "modeling"
        # G2 Phase 4 — Shelf state. `active_shelf` indexes into
        # SHELVES_DATA; click a tab to switch, click an icon in the
        # active strip to fire the action.
        self.active_shelf: str = "Polygons"
        # Phase 1 — Last Tool / Show-Manipulator / Soft Select toggles
        # (Maya Y / T / B). `_last_tool` is updated whenever the active
        # tool changes (see the keyboard tool_map dispatch); Y swaps it
        # with `self.tool`. `show_manipulator` gates the rotate-gizmo
        # arc paint pass; `soft_select_on` + `soft_select_radius` feed
        # Phase 12 sculpt + Phase 14 paint-skin-weights once they land.
        self._last_tool: str = "select"
        self.show_manipulator: bool = True
        self.soft_select_on:   bool = False
        self.soft_select_radius: float = 64.0
        # In-flight drag state for the new Phase 1 tools. None until a
